// BM-026: buildPrompt silently drops the speakers array — names never reach the prompt
@Test
func buildPromptIncludesSpeakerNamesWhenProvided() async throws {
    let plugin = MLXSummarizationPlugin()
    let transcript = "Quarterly planning session."
    // Distinctive names — none appear in the static prompt template or transcript above
    let speakers = ["Zephyra", "Theron", "Calixta"]

    // With speakers: every name must appear somewhere in the returned prompt
    let promptWithSpeakers = await plugin.buildPrompt(transcript: transcript, speakers: speakers, meetingType: .oneOnOne)
    #expect(promptWithSpeakers.contains("Zephyra"))
    #expect(promptWithSpeakers.contains("Theron"))
    #expect(promptWithSpeakers.contains("Calixta"))

    // Speaker names must appear before the transcript separator, confirming
    // they're injected into the prompt context — not lost or appended after.
    let separator = "---\n\(transcript)"
    let sepRange = try #require(promptWithSpeakers.range(of: separator))
    for name in speakers {
        let nameRange = try #require(promptWithSpeakers.range(of: name))
        #expect(
            nameRange.lowerBound < sepRange.lowerBound,
            "\(name) must appear BEFORE the transcript, not after"
        )
    }

    // Without speakers (empty array): none of these distinctive names should be present,
    // confirming the with-speakers assertions aren't trivially passing on boilerplate
    let promptNoSpeakers = await plugin.buildPrompt(transcript: transcript, speakers: [], meetingType: .oneOnOne)
    #expect(!promptNoSpeakers.contains("Zephyra"))
    #expect(!promptNoSpeakers.contains("Theron"))
    #expect(!promptNoSpeakers.contains("Calixta"))
}

