/// TASK-014 / F8/#197 — CalendarAwareMeetingDetector task handle safety.
///
/// CalendarAwareMeetingDetector is a Swift actor, so all its mutable state
/// (including task handles like `calendarListenerTask`) is actor-isolated and
/// safe from concurrent mutation by construction.
///
/// These tests verify:
///   1. Concurrent creation and use of multiple detectors does not crash
///      (no shared mutable state leaked outside actor isolation).
///   2. The detector correctly handles rapid calendar updates (multiple
///      `refreshCalendar` invocations) without accumulating unbounded timer tasks.
///   3. `start()` via `init` is effectively idempotent — creating the detector
///      once produces a stable, functional listener state.
@Suite("CalendarAwareMeetingDetector — task handle safety (F8/#197)", .serialized)
struct CalendarAwareMeetingDetectorTaskHandleTests {
    // MARK: - Helpers

    private func makeDetector(
        meetings: [CalendarMeeting] = [],
        startDebounce: TimeInterval = 0.05,
        armWindow: TimeInterval = 600.0
    ) async -> (CalendarAwareMeetingDetector, MockCalendarEngine, AudioSessionDetector) {
