    // MARK: - ISOL-004: Calendar refresh does not accumulate timer tasks

    /// Each `refreshCalendar` invocation must cancel prior timer tasks via
    /// `cancelAllTimers()` before scheduling new ones. This test verifies the
    /// observable contract — that rapid calendar updates don't produce duplicate
    /// meeting-start events — which is only possible if old timers are correctly cancelled.
    @Test("rapid calendar updates do not fire duplicate meeting-start events")
    func rapidCalendarUpdatesNoDuplicateEvents() async throws {
        let calendar = MockCalendarEngine()

        // Single meeting starting in 5 min (within arm window)
        let meeting = CalendarMeeting(
            id: MeetingID("m-rapid"),
            title: "Rapid Update Meeting",
            startDate: Date().addingTimeInterval(5 * 60),
            endDate: Date().addingTimeInterval(65 * 60),
            attendees: [],
            isRecurring: false,
            isAllDay: false,
            videoCallURL: nil,
            location: nil,
            organizer: nil,
            calendarName: nil,
            calendarSource: .local
        )
        await calendar.setMeetings([meeting])

        let audio = AudioSessionDetector(startDebounce: 0.05, stopDebounce: 0.05, autoListen: false)
        let config = MeetingDetectionConfig(
            startDebounce: 0.05,
            stopDebounce: 0.05,
            armWindow: 600.0, // 10 min — meeting at 5 min is within arm window
            graceWindow: 5.0,
            armTimeout: 900.0
        )
        let detector = CalendarAwareMeetingDetector(calendar: calendar, audioDetector: audio, config: config)
        let stream = detector.events()

        // Let the detector arm for the meeting
        try await Task.sleep(for: .milliseconds(150))

        // Simulate rapid calendar changes (would fire multiple refreshCalendar calls)
        // Each refresh cancels prior timers, so only one arm fires.
        // triggerCalendarChange() is nonisolated so no `await` needed.
        calendar.triggerCalendarChange()
        calendar.triggerCalendarChange()
        try await Task.sleep(for: .milliseconds(100))

        // Now trigger audio — armed state → emits meetingStarted
        await audio.simulateActivation()
        try await Task.sleep(for: .milliseconds(200))

        var events: [MeetingDetectorEvent] = []
        let collector = Task {
            for await event in stream {
                events.append(event)
                if events.count >= 2 { break }
            }
        }
        try await Task.sleep(for: .milliseconds(300))
        collector.cancel()

        // Only one meetingStarted should fire — `meetingActive` gate prevents duplicates
        let startedCount = events.filter { if case .meetingStarted = $0 { true } else { false } }.count
        #expect(
            startedCount <= 1,
            "meetingStarted must fire at most once per activation — duplicate fires indicate unconsumed armed state or timer task leak (\(startedCount) fires observed)"
        )
    }
